arguments.command:
curl -s -X POST "https://slack.com/api/conversations.history?token=<TOKEN>" -d "channel=C_INC&limit=100" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR:', d.get('error')); sys.exit(1)
for m in d['messages']:
    text=m.get('text','')
    if 'deploy complete' in text.lower():
        print(json.dumps({'ts':m['ts'],'user':m['user'],'text':text,'type':m.get('type'),'subtype':m.get('subtype')}, ensure_ascii=False))
"

